"""Testable read-only boundary between MCP tool calls and the Agent Reach CLI.

No shell, management command, browser login, cookies, installer, or upgrade is exposed.
The upstream CLI's JSON result, backend evidence and error codes survive intact.
"""
from __future__ import annotations

import json
import os
import re
import subprocess
import sys
from copy import deepcopy
from urllib.parse import urlsplit

from agent_reach.utils.url import domain_matches, normalize_public_http_url

DEFAULT_SOURCES = "web,github,youtube,v2ex,bilibili"
VALID_SOURCES = frozenset({
    "web", "github", "youtube", "v2ex", "bilibili", "reddit",
    "twitter", "facebook", "instagram", "xiaohongshu", "linkedin",
    "boss", "xueqiu", "xiaoyuzhou",
})
SEARCH_SOURCES = frozenset({
    "web", "github", "youtube", "bilibili", "reddit", "twitter", "facebook",
    "instagram", "xiaohongshu", "boss", "xueqiu",
})
MAX_QUERY = 500
MAX_LIMIT = 10
MAX_URL = 2048
CLI_TIMEOUT = 35
PROCESS_TIMEOUT = 40
SEARCH_TEXT_CHARS = 6000
READ_TEXT_CHARS = 48000
RAW_CHARS = 3000
SUBTITLE_LANG = re.compile(r"^[a-zA-Z][a-zA-Z0-9-]{1,15}$")


class BridgeError(ValueError):
    """Rejected at the MCP boundary, before any subprocess starts."""


class ReachBridge:
    def __init__(self, enabled_sources: str | None = None):
        value = DEFAULT_SOURCES if enabled_sources is None else enabled_sources
        # An explicit empty configuration intentionally disables all sources.
        selected = {item.strip().lower() for item in value.split(",") if item.strip()}
        unknown = selected - VALID_SOURCES
        if unknown:
            raise BridgeError(f"unknown channel(s): {', '.join(sorted(unknown))}")
        self.enabled_sources = tuple(sorted(selected))

    def _invoke(self, arguments: list[str], *, max_chars: int = SEARCH_TEXT_CHARS) -> dict:
        command = [sys.executable, "-m", "agent_reach.cli", *arguments]
        try:
            completed = subprocess.run(
                command, check=False, capture_output=True, text=True, encoding="utf-8",
                errors="replace", timeout=PROCESS_TIMEOUT, shell=False,
            )
        except subprocess.TimeoutExpired:
            return self._error("TIMEOUT", "Agent Reach exceeded the request time budget")
        except OSError:
            return self._error("NEED_SETUP", "The Agent Reach runtime could not start")
        # Never echo stderr (may contain third-party account or network details).
        if len(completed.stdout) > 8_000_000:
            return self._error("INVALID_UPSTREAM_RESPONSE", "Agent Reach response is too large")
        try:
            data = json.loads(completed.stdout)
        except (json.JSONDecodeError, TypeError):
            return self._error("INVALID_UPSTREAM_RESPONSE", "Agent Reach did not return JSON")
        if not isinstance(data, dict) or not isinstance(data.get("ok"), bool):
            return self._error("INVALID_UPSTREAM_RESPONSE", "Agent Reach returned an invalid envelope")
        if completed.returncode and data["ok"]:
            return self._error("INVALID_UPSTREAM_RESPONSE", "Agent Reach returned conflicting process status")
        if not data["ok"] and not isinstance(data.get("error"), dict):
            return self._error("INVALID_UPSTREAM_RESPONSE", "Agent Reach omitted error details")
        if not data["ok"]:
            data = deepcopy(data)
            err = data["error"]
            err["message"] = str(err.get("message", ""))[:600]
            err["hint"] = str(err.get("hint", ""))[:600]
            return data
        data = deepcopy(data)
        # Preserve source URLs, backend and attempts while bounding context size.
        truncated = 0
        if isinstance(data.get("items"), list):
            limited = data["items"][:MAX_LIMIT]
            for item in limited:
                if not isinstance(item, dict):
                    continue
                body = item.get("text")
                if isinstance(body, str) and len(body) > max_chars:
                    item["text"] = body[:max_chars] + "\n[TRUNCATED by MCP bridge; read original URL for more]"
                    truncated += 1
                raw = item.get("raw")
                if raw is not None and len(json.dumps(raw, default=str)) > RAW_CHARS:
                    item["raw"] = {"bridge_note": "raw payload omitted (too large); source URL retained"}
                    truncated += 1
            data["items"] = limited
        meta = data.get("meta") if isinstance(data.get("meta"), dict) else {}
        meta["bridge_truncated_items"] = truncated
        meta["bridge_read_only"] = True
        data["meta"] = meta
        return data

    @staticmethod
    def _error(code: str, message: str) -> dict:
        return {"schema_version": 1, "ok": False, "backend": None, "items": [],
                "meta": {"bridge_read_only": True},
                "error": {"code": code, "message": message, "hint": ""}}

    def search(self, query: str, source: str = "web", limit: int = 5) -> dict:
        if not isinstance(source, str):
            raise BridgeError("source must be a channel name")
        source = source.strip().lower()
        if source not in self.enabled_sources:
            raise BridgeError(f"channel '{source}' is not enabled")
        if source not in SEARCH_SOURCES:
            raise BridgeError(f"channel '{source}' has no search action")
        if not isinstance(query, str) or not query.strip() or len(query) > MAX_QUERY:
            raise BridgeError(f"query must be 1 to {MAX_QUERY} characters")
        if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= MAX_LIMIT:
            raise BridgeError(f"limit must be between 1 and {MAX_LIMIT}")
        return self._invoke([source, "search", query.strip(), "--limit", str(limit),
                             "--timeout", str(CLI_TIMEOUT)])

    def read_url(self, url: str) -> dict:
        if not isinstance(url, str) or len(url) > MAX_URL:
            raise BridgeError("url must be a public HTTP(S) URL")
        try:
            normalized = normalize_public_http_url(url)
        except ValueError as exc:
            raise BridgeError("url must be a public HTTP(S) URL") from exc
        # The web reader is the fallback for URLs without enabled site channels.
        if "web" not in self.enabled_sources:
            raise BridgeError("web channel is not enabled")
        return self._invoke(["read", normalized, "--timeout", str(CLI_TIMEOUT)],
                            max_chars=READ_TEXT_CHARS)

    def subtitles(self, video_url: str, language: str = "en") -> dict:
        if "youtube" not in self.enabled_sources:
            raise BridgeError("channel 'youtube' is not enabled")
        if not isinstance(video_url, str) or len(video_url) > MAX_URL:
            raise BridgeError("a valid YouTube URL is required")
        try:
            normalized = normalize_public_http_url(video_url)
        except ValueError as exc:
            raise BridgeError("a valid YouTube URL is required") from exc
        host = (urlsplit(normalized).hostname or "").lower().rstrip(".")
        if not domain_matches(host, "youtube.com", "youtu.be", "youtube-nocookie.com"):
            raise BridgeError("a YouTube video URL is required")
        if not isinstance(language, str) or not SUBTITLE_LANG.fullmatch(language):
            raise BridgeError("language must be a short BCP-47-style code, e.g. en")
        return self._invoke(["youtube", "subtitle", normalized, "--lang", language,
                             "--timeout", str(CLI_TIMEOUT)], max_chars=READ_TEXT_CHARS)

    def status(self) -> dict:
        version = self._invoke(["version"])
        return {"ok": bool(version.get("ok")), "read_only": True,
                "enabled_sources": list(self.enabled_sources),
                "upstream": version.get("result", None), "error": version.get("error")}
