"""ChatGPT-facing MCP tools for genuine Agent Reach 1.6.1.

Deploy behind a Secure MCP Tunnel or private authenticated HTTPS gateway.
The service itself is not an auth server and must not be exposed publicly.
"""
from __future__ import annotations

import os

from mcp.server import MCPServer

from .core import ReachBridge

bridge = ReachBridge(enabled_sources=os.environ.get("REACH_MCP_CHANNELS"))
mcp = MCPServer("GMRI Agent Reach - read-only research")


@mcp.tool()
def reach_status() -> dict:
    """Read-only: show enabled research channels and the installed Agent Reach version.

    Does not fetch external content, log in, install software, or update anything.
    """
    return bridge.status()


@mcp.tool()
def reach_search(query: str, source: str = "web", limit: int = 5) -> dict:
    """Search public research sources via Agent Reach; return linked results and backend evidence.

    source: web, github, youtube, bilibili, or an explicitly enabled optional
    channel such as reddit. limit: 1 to 10. This tool only reads/searches.
    Error codes distinguish rate limits, setup gaps, login needs and failures.
    """
    return bridge.search(query, source, limit)


@mcp.tool()
def reach_read(url: str) -> dict:
    """Retrieve public URL content via Agent Reach. Include title, URL, text and backend receipt.

    Only HTTP(S) URLs are accepted; internal hosts and file URLs are rejected.
    Unenabled platform channels use the public web reader, not saved logins.
    No post, publish, comment, like, login, installation or updates.
    """
    return bridge.read_url(url)


@mcp.tool()
def reach_subtitles(video_url: str, language: str = "en") -> dict:
    """Retrieve a YouTube video's available subtitle text with source URL and backend receipt.

    The user must supply a YouTube video URL. No audio transcription or downloads
    are promised if the upstream cannot access captions; errors remain explicit.
    """
    return bridge.subtitles(video_url, language)


def start() -> None:
    host = os.environ.get("REACH_MCP_HOST", "127.0.0.1")
    port = int(os.environ.get("REACH_MCP_PORT", "8000"))
    if not 1 <= port <= 65535:
        raise ValueError("REACH_MCP_PORT must be between 1 and 65535")
    mcp.run(
        transport="streamable-http", host=host, port=port,
        stateless_http=True, json_response=True,
    )


if __name__ == "__main__":
    start()
